48	    if (!card) {
49	      return;
50	    }
51	
52	    const updateWidth = (nextWidth?: number) => {
53	      const width = Math.round(nextWidth ?? card.getBoundingClientRect().width);
54	      setCardWidth((prev) => (prev === width ? prev : width));
55	    };
56	
57	    updateWidth();
58	
59	    if (typeof ResizeObserver === "undefined") {
60	      const handleResize = () => updateWidth();
61	      window.addEventListener("resize", handleResize);
62	      return () => window.removeEventListener("resize", handleResize);
63	    }
64	
65	    const resizeObserver = new ResizeObserver((entries) => {
66	      updateWidth(entries[0]?.contentRect.width);
67	    });
68	
69	    resizeObserver.observe(card);
70	    return () => resizeObserver.disconnect();
71	  }, []);
72	
73	  const contextValue = useMemo(
74	    () => ({
75	      memo: memoData,
76	      creator,
77	      currentUser,
78	      parentPage,
79	      cardWidth,
